function validate([mat, target]) {
  if (!Array.isArray(mat) || mat.length < 1 || mat.length > 70) return 'mat needs 1 to 70 rows.';
  const n = Array.isArray(mat[0]) ? mat[0].length : 0;
  if (n < 1 || n > 70) return 'Each row needs 1 to 70 numbers.';
  for (const row of mat) {
    if (!Array.isArray(row) || row.length !== n) return 'Every row must have the same length.';
    if (row.some(v => !Number.isInteger(v) || v < 1 || v > 70)) return 'Every number in mat is an integer from 1 to 70.';
  }
  if (!Number.isInteger(target) || target < 1 || target > 800) return 'target is an integer from 1 to 800.';
  return null;
}

