function minimizeTheDifference(mat, target) {
  let reachable = new Array(target + 1).fill(false);
  reachable[0] = true;
  let over = Infinity;

  for (const row of mat) {
    const next = new Array(target + 1).fill(false);
    let nextOver = Infinity;
    for (const value of row) {
      nextOver = Math.min(nextOver, over + value);
      for (let sum = 0; sum <= target; sum++) {
        if (!reachable[sum]) {
          continue;
        }
        if (sum + value <= target) {
          next[sum + value] = true;
        } else {
          nextOver = Math.min(nextOver, sum + value);
        }
      }
    }
    reachable = next;
    over = nextOver;
  }

  let best = over - target;
  for (let sum = 0; sum <= target; sum++) {
    if (reachable[sum]) {
      best = Math.min(best, target - sum);
    }
  }
  return best;
}

