function minimizeTheDifference(mat, target) {
  // Keep every total that can be made, with no pruning at all.
  let totals = new Set([0]);
  for (const row of mat) {
    const grown = new Set();
    for (const t of totals) for (const v of row) grown.add(t + v);
    totals = grown;
  }
  let answer = Infinity;
  for (const t of totals) answer = Math.min(answer, Math.abs(target - t));
  return answer;
}

