function generate(rand, size) {
  const large = size === 'large';
  const m = large ? 50 + Math.floor(rand() * 21) : 1 + Math.floor(rand() * 4);
  const n = large ? 50 + Math.floor(rand() * 21) : 1 + Math.floor(rand() * 4);
  const top = rand() < 0.5 ? 70 : 1 + Math.floor(rand() * 15);
  // Sometimes every value is a multiple of step, so many targets cannot be hit exactly.
  const step = rand() < 0.4 ? 2 + Math.floor(rand() * 9) : 1;
  const levels = Math.max(1, Math.floor(top / step));
  const mat = Array.from({ length: m }, () => Array.from({ length: n }, () => step * (1 + Math.floor(rand() * levels))));
  // Aim the target near the reachable totals most of the time, anywhere in range otherwise.
  const mode = rand();
  let target;
  if (mode < 0.15) target = 1 + Math.floor(rand() * 800);
  else if (large && mode < 0.3) target = 1 + Math.floor(rand() * m);
  else target = Math.min(800, 1 + Math.floor(rand() * (m * top + 10)));
  return [mat, target];
}
